import { test, expect } from '@playwright/test';

test.describe('Account Locking Feature', () => {
  const username = 'adminUser';
  const password = 'correctPassword';

  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should lock account after 5 failed login attempts', async ({ page }) => {
    for (let i = 0; i < 5; i++) {
      await page.getByLabel('Username').fill(username);
      await page.getByLabel('Password').fill('wrongPassword');
      await page.getByRole('button', { name: 'Login' }).click();
      await expect(page.getByText('Invalid credentials')).toBeVisible();
    }

    await page.getByLabel('Username').fill(username);
    await page.getByLabel('Password').fill(password);
    await page.getByRole('button', { name: 'Login' }).click();

    await expect(page.getByText('Your account is locked due to multiple failed login attempts')).toBeVisible();
  });

  test('should allow admin to reset locked account', async ({ page }) => {
    // Assuming the account is already locked from the previous test
    await page.goto('/admin');
    await page.getByRole('button', { name: 'Unlock Account' }).click();

    await expect(page.getByText('Account unlocked successfully')).toBeVisible();

    await page.goto('/login');
    await page.getByLabel('Username').fill(username);
    await page.getByLabel('Password').fill(password);
    await page.getByRole('button', { name: 'Login' }).click();

    await expect(page.getByText('Welcome back!')).toBeVisible();
  });
});
